'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DEMO='assets/source-3.png';
let demoProcessed=DEMO;
const state={screen:'home',type:'video',tool:'box',src:DEMO,aspect:1264/848,duration:12,time:0,playing:false,regions:[],selected:null,nextId:1,history:[],future:[],sheet:null,before:false,zoom:1,pan:{x:0,y:0},crop:null,cropRatio:'Original',intro:0,tab:'video',progress:0,resultSrc:null,effectSrc:null,savedId:null,resultFrom:'home',savedSignature:null,controlsHidden:false,themeMode:'system'};
let gallery=[];try{gallery=JSON.parse(localStorage.getItem('remove-gallery-v1')||'[]');state.themeMode=localStorage.getItem('remove-theme')||'system';}catch{}
function applyTheme(){const dark=state.themeMode==='dark'||(state.themeMode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('dark',dark);}
applyTheme();
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.themeMode==='system')applyTheme();});

let lastDraft=null,deletedResult=null,sheetOpener=null;
let dbPromise;
function mediaDatabase(){if(!dbPromise)dbPromise=new Promise(resolve=>{if(!window.indexedDB){resolve(null);return;}const req=indexedDB.open('remove-prototype-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('results',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);});return dbPromise;}
async function mediaStore(mode,fn){try{const db=await mediaDatabase();if(!db)return;const tx=db.transaction('results',mode);fn(tx.objectStore('results'));}catch{}}
function persistDraft(){lastDraft={type:state.type,src:state.src,aspect:state.aspect,duration:state.duration,time:state.time,regions:JSON.parse(JSON.stringify(state.regions)),selected:state.selected,nextId:state.nextId,savedId:state.savedId,savedSignature:state.savedSignature};}
function resumeDraft(){if(!lastDraft)return;stopPlayback();Object.assign(state,JSON.parse(JSON.stringify(lastDraft)),{screen:'edit',sheet:null,tool:'box',history:[],future:[],zoom:1,pan:{x:0,y:0},crop:null});render();}
function mediaSignature(){return JSON.stringify({src:state.src,type:state.type,duration:state.duration,regions:state.regions});}
function chooseRegion(id){const r=state.regions.find(r=>r.id===id);if(!r)return;stopPlayback();state.selected=id;state.tool=r.kind;if(state.type==='video'&&(state.time<r.start||state.time>r.end))state.time=r.start;}
function requestNewEditor(type,src=DEMO,aspect=1264/848,duration=state.duration){newEditor(type,src,aspect,duration);}
function reviewExample(){newEditor('video');state.regions=[{id:1,kind:'box',x:57,y:65,w:19,h:13,start:0,end:Math.round(state.duration*.67*100)/100},{id:2,kind:'box',x:30,y:25,w:16,h:17,start:state.duration*.25,end:Math.round(state.duration*5/6*100)/100}];state.nextId=3;state.selected=2;state.time=state.duration*5/12;render();}
function closeSheet(){const target=sheetOpener;sheetOpener=null;state.sheet=null;render();requestAnimationFrame(()=>$(`[data-action="${target}"]`)?.focus({preventScroll:true}));}

let drag=null,playTimer=null,processTimer=null,toastTimer=null,uploadType='image',hideControlsTimer=null;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function timeText(t,precise=false){t=Math.max(0,Number(t)||0);const units=precise?Math.round(t*100):Math.floor(t)*100,h=Math.floor(units/360000),m=Math.floor(units%360000/6000),s=Math.floor(units%6000/100);return `${h?h+':':''}${h?String(m).padStart(2,'0'):m}:${String(s).padStart(2,'0')}${precise?'.'+String(units%100).padStart(2,'0'):''}`;}
function playerTime(t){const text=timeText(t);return t<3600?text.padStart(5,'0'):text;}
function parseTime(s){const text=String(s).trim();if(!/^\d+(?::\d{1,2}){0,2}(?:\.\d{1,2})?$/.test(text))return NaN;const p=text.split(':').map(Number);if(p.length>1&&p.slice(1).some(n=>n>=60))return NaN;return p.reduce((a,v)=>a*60+v,0);}
function selected(){return state.regions.find(r=>r.id===state.selected);}
function statusBar(){return '<div class="status-bar"><span>9:30</span><span class="status-icons">◢ ▰ <i class="battery"></i></span></div>';}
function topbar(title,right='',back='home'){return `<header class="app-bar"><button class="icon-button" aria-label="Back" data-action="${back}">${icon('arrow')}</button><h2 class="app-title">${title}</h2>${right}</header>`;}
function toast(message,action=null){const el=$('#toast');el.innerHTML=`<span>${esc(message)}</span>${action?`<button data-action="${action}">Undo</button>`:''}`;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),action?6500:3200);}
function stopPlayback(){state.playing=false;state.controlsHidden=false;clearTimeout(hideControlsTimer);hideControlsTimer=null;clearInterval(playTimer);playTimer=null;}
function applyControlsVisibility(){$$('.result-controls').forEach(el=>el.classList.toggle('controls-hidden',state.controlsHidden));}
function scheduleHideControls(){clearTimeout(hideControlsTimer);hideControlsTimer=setTimeout(()=>{state.controlsHidden=true;applyControlsVisibility();},2600);}
function go(screen){stopPlayback();if(state.screen==='processing'){clearInterval(processTimer);processTimer=null;}state.screen=screen;state.sheet=null;state.before=false;if(screen==='home')heroIntroStart=performance.now();render();}
function snapshot(){return JSON.stringify({regions:state.regions,selected:state.selected,src:state.src,aspect:state.aspect});}
function remember(){state.history.push(snapshot());if(state.history.length>30)state.history.shift();state.future=[];}
function undo(redo=false){const from=redo?state.future:state.history,to=redo?state.history:state.future;if(!from.length)return;to.push(snapshot());Object.assign(state,JSON.parse(from.pop()));render();}
function saveGallery(){gallery=gallery.slice(0,30);try{localStorage.setItem('remove-gallery-v1',JSON.stringify(gallery.filter(g=>g.src===DEMO).map(({preview,...g})=>g)));}catch{}mediaStore('readwrite',store=>{gallery.forEach(item=>store.put(item));});}
function newEditor(type,src=DEMO,aspect=1264/848,duration=state.duration){stopPlayback();Object.assign(state,{screen:'edit',type,src,aspect,duration,tool:'box',regions:[],selected:null,nextId:1,history:[],future:[],time:0,zoom:1,pan:{x:0,y:0},sheet:null,crop:null,resultSrc:null,effectSrc:null,savedId:null,savedSignature:null,resultFrom:'home'});render();}
function renderNav(){const entries=[['home','01','Головна'],['edit','02','Редактор'],['result','03','Результат'],['gallery','04','Галерея']];$('#screen-nav').innerHTML=entries.map(([s,n,t])=>`<button class="screen-link ${(state.screen==='viewer'?state.resultFrom:state.screen)===s||(s==='result'&&state.screen==='processing')?'active':''}" data-action="nav-${s}"><span class="num">${n}</span><span>${t}</span><i class="nav-dot"></i></button>`).join('');$('#screen-caption').textContent=({home:'01 / HOME',edit:'02 / EDITOR',processing:'03 / PROCESSING',result:'03 / RESULT',viewer:'04 / VIEWER',gallery:'04 / MY GALLERY',intro:'00 / INTRO'})[state.screen];$('#theme-toggle').classList.toggle('on',document.body.classList.contains('dark'));const select=$('#duration-setting');if(select){for(const o of [...select.options])if(o.dataset.custom)o.remove();if(![...select.options].some(o=>Number(o.value)===state.duration)){const o=new Option(timeText(state.duration)+' · custom',String(state.duration));o.dataset.custom='true';select.add(o);}select.value=String(state.duration);}}
function renderGuide(){const guides={home:['Почни з прикладу',[['Обери фото або відео','Відкрий демо або завантаж свій файл із пристрою.'],['Посунь розділювач','Порівняй оригінал і приховування даних на тому самому фото.'],['Повернися до результатів','Готові файли зберігаються в My Gallery.']]],edit:['Менше кнопок. Більше ясності.',[['Познач область','Намалюй Box чи Lasso на зображенні. Або натисни Add box.'],['Потягни межі інтервалу','Кожна область має свій рядок. Ліва й права межі визначають початок і кінець.'],['Натисни Erase','За замовчуванням область діє на весь ролик. Точний час - натисканням на інтервал.']]],processing:['Дія має зворотний зв’язок',[['Обробка триває','Прогрес підтверджує, що натискання спрацювало.'],['Можна скасувати','Області та їхні інтервали залишаться в редакторі.']]],result:['Готово означає збережено',[['Порівняй результат','Compare перемикає Before / After без зміни позиції.'],['Уточни виділення','Edit повертає до цього самого демо з твоїми областями.'],['Збережи на пристрій','Демо експортується як PNG. У продукті тут буде експорт фото або відео.']]],gallery:['Результати, а не «проєкти»',[['Фото та відео окремо','Зрозумілий розділ із готовими результатами.'],['Відкрий збережене','Натисни мініатюру, щоб переглянути результат.']]],viewer:['Перегляд без зайвого',[['Фото на весь екран','Збережене фото відкривається на весь екран, без інтерфейсу результату.'],['Мінімальний плеєр','Для відео: Play/Pause, час і смуга прогресу. Відтворення імітується.'],['Назад там, де почав','Назад веде на головну або в My Gallery, звідки відкрито.']]],intro:['Спочатку пояснення',[['Три короткі кроки','Що робить апка, як позначити об’єкт і де знайти результат.'],['Без зайвого навчання','Демонстраційний вступ можна пропустити.']]]};const [title,steps]=guides[state.screen];$('#guide-title').textContent=title;$('#guide-content').innerHTML=steps.map(([t,p],i)=>`<div class="guide-step"><span>0${i+1}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('');}
function thumb(item,index=0){return `<button class="thumb" data-action="open-gallery" data-index="${index}" aria-label="Open saved ${item.type==='video'?'video':'image'} ${index+1}"><img src="${esc(item.preview||item.src)}" alt="Saved ${item.type==='video'?'video':'image'} preview" decoding="async">${item.type==='video'?`<span class="thumb-time">${icon('play')}${timeText(item.duration)}</span>`:''}</button>`;}
function home(){const recent=gallery.slice(0,8);return `<div class="home-screen">${statusBar()}<div class="hero" style="--split:50%"><img class="hero-img" src="${DEMO}" alt="A car number plate before and after cleanup"><div class="hero-after"><img class="hero-processed" src="${demoProcessed}" alt=""></div><div class="hero-line"><span>‹ ›</span></div><span class="hero-label left">Before</span><span class="hero-label right">After</span><input class="hero-range" aria-label="Before and after comparison" type="range" min="5" max="95" value="50"><button class="icon-button home-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button></div><div class="home-content"><h2 class="home-heading">Let’s start</h2><button class="media-card" data-action="pick-video">${icon('video')}<div><strong>Select video</strong><small>Pick a video to clean</small></div>${icon('chevron','chevron')}</button><button class="media-card" data-action="pick-image">${icon('image')}<div><strong>Select image</strong><small>Pick a photo to clean</small></div>${icon('chevron','chevron')}</button><div class="section-heading"><h3>My gallery</h3><button data-action="gallery">See all</button></div>${recent.length?`<div class="recent-grid">${recent.map(thumb).join('')}</div>`:`<div class="gallery-empty" role="status">${icon('gallery')}<span><strong>Your results will appear here</strong><small>Saved automatically after you tap Erase.</small></span></div>`}</div></div>`;}
function shapeMarkup(r){const active=r.id===state.selected,cls=`selection-shape ${active?'selected':''}`,opacity=!active&&state.type==='video'&&(state.time<r.start||state.time>r.end)?'.32':'1';const points=r.points?r.points.map(p=>`${p.x},${p.y}`).join(' '):'';return `<g class="region ${active?'active':'inactive'}" data-region="${r.id}" opacity="${opacity}">${r.kind==='lasso'?`<polygon class="${cls}" points="${points}" data-shape="${r.id}"/>`:`<rect class="${cls}" x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" data-shape="${r.id}"/>`}${active&&r.kind==='box'?[[r.x,r.y],[r.x+r.w,r.y],[r.x,r.y+r.h],[r.x+r.w,r.y+r.h]].map(([x,y],i)=>`<g class="resize-handle" style="transform:translate(${x}px,${y}px) scale(calc(1 / var(--sx,3.6)),calc(1 / var(--sy,2.4)))"><circle class="resize-hit" r="14" data-resize="${r.id}" data-corner="${i}"/><circle class="resize-dot" r="6" data-resize="${r.id}" data-corner="${i}"/></g>`).join(''):''}<rect class="region-label-bg" data-shape="${r.id}" x="${r.x}" y="${Math.max(0,r.y-5)}" width="5" height="5" rx="1"/><text class="region-number" x="0" y="0" text-anchor="middle" dominant-baseline="central" style="transform:translate(${r.x+2.5}px,${Math.max(0,r.y-5)+2.5}px) scale(calc(1 / var(--sx,3.6)),calc(1 / var(--sy,2.4)))">${r.id}</text></g>`;}
function selectionSvg(){return `<svg class="selection-svg" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Draw or move a selection">${state.regions.map(shapeMarkup).join('')}</svg>`;}
function cropFrame(){const c=state.crop;return `<div class="crop-frame" style="left:${c.x}%;top:${c.y}%;width:${c.w}%;height:${c.h}%"><i class="crop-corner tl"></i><i class="crop-corner tr"></i><i class="crop-corner bl"></i><i class="crop-corner br" data-crop-resize="true"></i></div>`;}
function plane(interactive=true){return `<div class="media-plane" style="aspect-ratio:${state.aspect};transform:translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom})"><img src="${esc(state.src)}" alt="Media being edited" draggable="false">${interactive?(state.tool==='crop'?cropFrame():selectionSvg()):effectsMarkup()} </div>`;}
function effectsMarkup(){if(state.before||!state.effectSrc)return '';return `<div class="effects-layer">${state.regions.filter(r=>state.type!=='video'||state.time>=r.start&&state.time<=r.end).map(r=>`<img class="processed-region" src="${state.effectSrc}" alt="" style="clip-path:${r.points?'polygon('+r.points.map(p=>p.x+'% '+p.y+'%').join(',')+')':'inset('+r.y+'% '+(100-r.x-r.w)+'% '+(100-r.y-r.h)+'% '+r.x+'%)'}">`).join('')}</div>`;}
function tools(){return `<nav class="tools" aria-label="Selection tools">${['box','lasso','crop'].map(t=>`<button class="tool ${state.tool===t?'active':''}" data-action="tool-${t}" aria-pressed="${state.tool===t}">${icon(t)}<span>${t[0].toUpperCase()+t.slice(1)}</span></button>`).join('')}</nav>`;}
function rulerLabel(n){return state.duration<=15?Math.round(n)+'s':timeText(n);}
function timeline(){const marks=Array.from({length:13},(_,i)=>i%3===0?`<span class="ruler-tick ${i===0?'first':i===12?'last':''}" style="left:${i/12*100}%">${rulerLabel(i*state.duration/12)}</span>`:`<i class="ruler-dot" style="left:${i/12*100}%" aria-hidden="true"></i>`);return `<div class="timeline" style="--progress:${state.time/state.duration}"><div class="timeline-media"><div class="ruler">${marks.join('')}</div><div class="filmstrip">${Array.from({length:7},()=>`<img src="${esc(state.src)}" alt="" draggable="false">`).join('')}<div class="scrub-hit" aria-label="Scrub video" role="slider" tabindex="0" aria-valuemin="0" aria-valuemax="${state.duration}" aria-valuenow="${state.time}"></div></div><div class="watched-progress" aria-hidden="true"></div></div><div class="tracks-shell"><div class="tracks">${state.regions.map(r=>`<div class="track-row"><div class="track ${state.selected===r.id?'active':''}" data-track="${r.id}" role="group" tabindex="0" aria-label="${r.kind} ${r.id}, ${timeText(r.start)} to ${timeText(r.end)}" style="left:${r.start/state.duration*100}%;width:${(r.end-r.start)/state.duration*100}%"><span class="track-name">${r.kind==='box'?'Box':'Lasso'} ${r.id}</span>${state.selected===r.id?`<span class="track-grip start" data-handle="start" data-id="${r.id}" role="slider" tabindex="0" aria-label="Selection start time" aria-valuemin="0" aria-valuemax="${r.end}" aria-valuenow="${r.start}"></span><span class="track-grip end" data-handle="end" data-id="${r.id}" role="slider" tabindex="0" aria-label="Selection end time" aria-valuemin="${r.start}" aria-valuemax="${state.duration}" aria-valuenow="${r.end}"></span>`:''}</div></div>`).join('')}${!state.regions.length?'<div class="empty-timeline">Draw around an object, or tap + Add box</div>':''}</div></div><div class="time-tooltip" aria-live="off"></div><div class="playhead"></div></div>`;}
function context(){const r=selected();if(!r)return state.type==='video'?`<div class="selection-context empty-context">Select an object. It applies to the whole video by default.</div>`:'';const outside=state.type==='video'&&(state.time<r.start||state.time>r.end);return `<div class="selection-context"><strong>${r.kind==='box'?'Box':'Lasso'} ${r.id}</strong>${state.type==='video'?`<button class="context-interval" data-action="time" aria-label="Edit interval for ${r.kind} ${r.id}">${timeText(r.start,true)} – ${timeText(r.end,true)}</button>`:'<span style="flex:1"></span>'}<button class="context-delete" data-action="delete-region" aria-label="Delete selected area">${icon('trash')}</button></div>`;}
function editor(){return `<div class="editor">${topbar('Edit',`<button class="icon-button" data-action="undo" aria-label="Undo" ${state.history.length?'':'disabled'}>${icon('undo')}</button><button class="icon-button" data-action="redo" aria-label="Redo" ${state.future.length?'':'disabled'}>${icon('redo')}</button><button class="primary small" data-action="erase" ${state.regions.length&&state.tool!=='crop'?'':'disabled'}>Erase</button>`)}<div class="stage">${plane()}${!state.regions.length&&state.tool!=='crop'?`<div class="draw-hint">${state.tool==='lasso'?'Trace around what you want to remove':'Draw a box around an object'}</div>`:''}${state.tool!=='crop'?`<div class="zoom-tools"><button data-action="zoom-out" aria-label="Zoom out">−</button><button class="zoom-value" data-action="zoom-reset" aria-label="Reset zoom">${Math.round(state.zoom*100)}%</button><button data-action="zoom-in" aria-label="Zoom in">+</button></div>`:''}</div>${state.tool==='crop'?cropControls():`${state.type==='video'?`<div class="playback"><button class="icon-button" data-action="play" aria-label="${state.playing?'Pause':'Play'}">${icon(state.playing?'pause':'play')}</button><div class="time-readout">${timeText(state.time)} <span>/ ${timeText(state.duration)}</span></div>${state.tool==='lasso'?'<span class="draw-mode-label">Trace to add an area</span>':`<button class="subtle" data-action="add">${icon('plus')} Add box</button>`}</div>${timeline()}`:`<div class="photo-add"><span>${state.regions.length?state.regions.length+' area'+(state.regions.length>1?'s':''):'Select an area to remove'}</span>${state.tool==='lasso'?'<span class="draw-mode-label">Trace to add an area</span>':`<button class="subtle" data-action="add">${icon('plus')} Add box</button>`}</div>${regionChips()}`}${context()}${tools()}`}</div>`;}
function regionChips(){if(!state.regions.length)return '';return `<div class="region-chips-shell"><div class="region-chips" role="tablist" aria-label="Selected areas">${state.regions.map(r=>`<button class="region-chip ${state.selected===r.id?'active':''}" data-track="${r.id}" role="tab" aria-selected="${state.selected===r.id}">${icon(r.kind)}<span>${r.kind==='box'?'Box':'Lasso'} ${r.id}</span></button>`).join('')}</div></div>`;}
function cropControls(){return `<div class="crop-options"><header><span>Aspect ratio</span><button class="text-button" data-action="crop-reset">Reset</button></header><div class="ratios">${['Original','1:1','9:16','16:9','Free'].map(r=>`<button class="ratio ${state.cropRatio===r?'active':''}" data-action="ratio" data-ratio="${r}">${r}</button>`).join('')}</div></div><div class="crop-confirm"><button class="text-button" data-action="crop-cancel">Cancel</button><button class="primary" data-action="crop-apply">${icon('check')} Apply crop</button></div>`;}
function viewer(){const video=state.type==='video';return `<div class="viewer ${video?'is-video':'is-photo'}">${statusBar()}<div class="viewer-stage" data-action="toggle-controls">${plane(false)}</div><div class="viewer-top"><button class="viewer-btn" data-action="${state.resultFrom==='gallery'?'gallery':'home'}" aria-label="Back">${icon('arrow')}</button><button class="viewer-btn" data-action="system-share" aria-label="More options">${icon('more')}</button></div>${video?`<div class="result-controls viewer-controls ${state.controlsHidden?'controls-hidden':''}"><div class="result-controls-top"><button class="icon-button" data-action="play" aria-label="${state.playing?'Pause demo preview':'Play demo preview'}">${icon(state.playing?'pause':'play')}</button><div class="result-time" aria-label="Playback time"><span class="result-current">${timeText(state.time)}</span><span class="result-time-divider" aria-hidden="true">/</span><span class="result-duration">${timeText(state.duration)}</span></div></div><input type="range" min="0" max="${state.duration}" step=".01" value="${state.time}" aria-label="Video position" class="result-scrub" style="--played:${state.time/state.duration*100}%"></div>`:''}</div>`;}
function result(){return `${topbar('Result',`<button class="icon-button delete-button" data-action="delete-result" aria-label="Delete this result">${icon('trash')}</button>`,'edit-again')}<div class="result"><div class="result-view" data-action="toggle-controls">${plane(false)}${state.before?'<span class="result-state">Before</span>':''}<button class="compare-button ${state.before?'before':''}" data-action="compare" aria-label="${state.before?'Show result':'Show original'}" aria-pressed="${state.before}">${icon('compare')}</button>${state.type==='video'?`<div class="result-controls ${state.controlsHidden?'controls-hidden':''}"><div class="result-controls-top"><button class="icon-button" data-action="play" aria-label="${state.playing?'Pause demo preview':'Play demo preview'}">${icon(state.playing?'pause':'play')}</button><div class="result-time" aria-label="Playback time"><span class="result-current">${timeText(state.time)}</span><span class="result-time-divider" aria-hidden="true">/</span><span class="result-duration">${timeText(state.duration)}</span></div></div><input type="range" min="0" max="${state.duration}" step=".01" value="${state.time}" aria-label="Result position" class="result-scrub" style="--played:${state.time/state.duration*100}%"></div>`:''}</div><p class="result-saved">${icon('check-circle')}Saved</p><div class="result-buttons"><button class="result-edit" data-action="edit-again">${icon('edit')} Edit</button><button class="primary result-main" data-action="home">${icon('house')} Go to Main</button></div><div class="share-row">${[['Instagram','instagram','share'],['WhatsApp','whatsapp','share'],['Facebook','facebook','share'],['More','more','system-share']].map(([name,g,a])=>`<button class="share-item" data-action="${a}" data-service="${name}" aria-label="${a==='share'?'Share via '+name:'More options'}"><span class="share-circle">${icon(g)}</span>${name}</button>`).join('')}</div></div>`;}
function galleryScreen(){const items=gallery.map((g,i)=>({...g,index:i})).filter(g=>g.type===state.tab);return `${topbar('My Gallery')}<nav class="gallery-tabs" role="tablist" aria-label="Media type">${['video','image'].map(t=>`<button class="gallery-tab ${state.tab===t?'active':''}" role="tab" aria-selected="${state.tab===t}" tabindex="${state.tab===t?0:-1}" data-action="tab-${t}">${t==='video'?'Videos':'Images'}</button>`).join('')}</nav>${items.length?`<div class="gallery-content"><div class="gallery-grid">${items.map(g=>thumb(g,g.index)).join('')}</div></div>`:`<div class="empty-gallery">${icon('gallery')}<h3>Your ${state.tab==='video'?'videos':'images'}, cleaned up.</h3><p>Once you tap Erase, your result<br>will appear here automatically.</p><button class="primary" data-action="pick-${state.tab}">${icon('plus')} Select ${state.tab==='video'?'video':'image'}</button></div>`}`;}
function processing(){return `${topbar('Processing','','cancel-process')}<div class="processing"><div class="processing-preview" style="--ar:${state.aspect}"><img src="${esc(state.src)}" alt="Selected media"><div class="scan-line"></div></div><h2>Removing selected areas</h2><div class="progress-shell" role="progressbar" aria-label="Processing progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.progress}"><div class="progress-fill" style="width:${state.progress}%"></div></div><span class="processing-percent">${state.progress}%</span></div>`;}
function intro(){const titles=['Remove unwanted<br>objects.','Mark the<br>object.','Tap Erase.<br>Keep the result.'];const bodies=['Clean up distractions and text in your photos and videos.','Draw a box or trace with Lasso. In a video, drag the ends of its row to set the time.','Your result is saved to My Gallery automatically. Compare it, edit again or share.'];return `<div class="intro"><div class="intro-top"><span>0${state.intro+1} / 03</span><button class="intro-skip" data-action="home">Skip</button></div><div class="intro-visual"><div class="intro-demo"><img class="intro-photo" src="${state.intro===2?demoProcessed:DEMO}" alt="Selecting a car number plate">${state.intro===1?'<div class="intro-mark"><span>1</span></div>':''}</div><div class="intro-pill">${icon(state.intro===0?'compare':state.intro===1?'box':'check')}${['Before / After','Box or Lasso','Saved to My Gallery'][state.intro]}</div></div><h2>${titles[state.intro]}</h2><p>${bodies[state.intro]}</p><div class="intro-dots" aria-label="Step ${state.intro+1} of 3">${[0,1,2].map(i=>`<span class="${i===state.intro?'active':''}"></span>`).join('')}</div><button class="primary" data-action="intro-next">${state.intro<2?'Next':'Continue'} ${icon('chevron')}</button></div>`;}
const SHARE_APPS={
  Instagram:{glyph:'instagram',title:'Share to Instagram',targets:t=>[['Feed','image','Post to your profile'],['Story','plus','Visible for 24 hours'],...(t==='video'?[['Reels','video','Short vertical video']]:[]),['Messages','share','Send in a chat']]},
  WhatsApp:{glyph:'whatsapp',title:'Send to WhatsApp',chats:[['My status','Updates disappear after 24 hours',true],['Family','Group · 6 members'],['Alex','Last seen today'],['Work team','Group · 12 members'],['Sam','Online']]},
  Facebook:{glyph:'facebook',title:'Share to Facebook',targets:()=>[['Feed','image','Post on your timeline'],['Story','plus','Visible for 24 hours']]}
};
function shareAppSheet(){const app=SHARE_APPS[state.shareApp]||SHARE_APPS.Instagram,name=state.shareApp,item=gallery.find(g=>g.id===state.savedId),thumbSrc=item?.preview||state.src,kind=state.type==='video'?'Video':'Photo';
const head=`<div class="share-app-head"><span class="share-app-icon">${icon(app.glyph)}</span><div><h2>${app.title}</h2><small>${kind}${state.type==='video'?' · '+timeText(state.duration):''}</small></div><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><div class="share-app-preview"><img src="${esc(thumbSrc)}" alt="Result preview"><span>Remove Unwanted result</span></div>`;
if(name==='WhatsApp')return `${head}<input class="share-app-search" type="text" placeholder="Search name or group" aria-label="Search contacts" data-share-search><div class="share-app-label">Recent chats</div><div class="share-chat-list">${app.chats.map(([n,sub,status])=>`<button class="share-chat" data-action="share-pick" data-target="${n}" aria-pressed="false"><span class="share-avatar ${status?'status':''}">${status?icon('plus'):n[0]}</span><span class="share-chat-text"><strong>${n}</strong><small>${sub}</small></span><span class="share-check">${icon('check')}</span></button>`).join('')}</div><button class="primary share-app-send" data-action="share-send" disabled>Send</button>`;
if(name==='Facebook')return `${head}<textarea class="share-app-caption" rows="2" placeholder="Say something about this…" aria-label="Post caption"></textarea><div class="share-app-label">Share to</div><div class="share-option-list">${app.targets().map(([n,g,sub],i)=>`<button class="share-option ${i===0?'selected':''}" data-action="share-option" data-target="${n}" aria-pressed="${i===0}"><span class="share-option-icon">${icon(g)}</span><span class="share-chat-text"><strong>${n}</strong><small>${sub}</small></span><span class="share-radio"></span></button>`).join('')}</div><button class="primary share-app-send" data-action="share-send">Share now</button>`;
return `${head}<div class="share-app-label">Share to</div><div class="share-target-grid">${app.targets(state.type).map(([n,g,sub])=>`<button class="share-target" data-action="share-send" data-target="${n}" aria-label="${n}: ${sub}"><span class="share-option-icon">${icon(g)}</span>${n}</button>`).join('')}</div>`;}
const SYSTEM_SHARE_CONTACTS=[['Alex','WhatsApp','whatsapp'],['Family','WhatsApp','whatsapp'],['Sam','Messages','chat'],['Work team','Email','mail']];
const SYSTEM_SHARE_APPS=[['Messages','chat'],['Email','mail'],['Drive','cloud'],['Instagram','instagram'],['WhatsApp','whatsapp'],['Facebook','facebook'],['Telegram','send'],['Bluetooth','bluetooth']];
function systemShareSheet(){const item=gallery.find(g=>g.id===state.savedId),thumbSrc=item?.preview||state.src,video=state.type==='video',appLink=state.shareSubject==='app';
return `${appLink?`<div class="sys-share-preview"><span class="sys-share-appmark" aria-hidden="true">r<span>.</span></span><div><strong>Remove Unwanted</strong><small>Sharing app link</small></div></div>`:''}<div class="sys-share-preview"${appLink?' hidden':''}><img src="${esc(thumbSrc)}" alt="Result preview"><div><strong>Sharing 1 ${video?'video':'image'}</strong><small>Remove Unwanted result${video?' · '+timeText(state.duration):''}</small></div></div><div class="sys-share-chips"><button class="sys-share-chip" data-action="sys-share-copy">${icon('copy')}Copy</button><button class="sys-share-chip" data-action="sys-share-target" data-target="Quick Share">${icon('nearby')}Quick Share</button></div><div class="sys-share-row">${SYSTEM_SHARE_CONTACTS.map(([n,app,g])=>`<button class="sys-share-target" data-action="sys-share-target" data-target="${n} (${app})" aria-label="Share with ${n} on ${app}"><span class="sys-share-avatar">${n[0]}<i>${icon(g)}</i></span><span>${n}</span></button>`).join('')}</div><div class="sys-share-divider"></div><div class="sys-share-row sys-share-apps">${SYSTEM_SHARE_APPS.map(([n,g])=>`<button class="sys-share-target" ${SHARE_APPS[n]&&!appLink?`data-action="share" data-service="${n}"`:`data-action="sys-share-target" data-target="${n}"`} aria-label="Share via ${n}"><span class="sys-share-app">${icon(g)}</span><span>${n}</span></button>`).join('')}</div>`;}
const RES_PRESETS=[720,640,400,200],
RES_DESC={original:'Keep original resolution',720:'High quality, smaller file',640:'Good quality, less storage',400:'Lower quality, small file',200:'Lowest quality, smallest file'},
SPEEDS=[['faster','Faster','bolt','Compress quickly',2],['balanced','Balanced','scale','Best balance',1],['smaller','Smaller file','database','More compression time',.5]];
function speedInfo(){return SPEEDS.find(s=>s[0]===state.speed)||SPEEDS.find(s=>s[0]==='balanced')||SPEEDS[0];}
function resSource(){const {w,h}=state.sourceSize||{w:1264,h:848};return {w,h,short:Math.min(w,h)};}
function resLabel(v=state.resolution){return v==='original'||!v?'Original':String(v);}
function resOptions(){const {w,h,short}=resSource(),presets=RES_PRESETS.filter(p=>p<short);return [['original',`${w}x${h}`,RES_DESC.original],...presets.map(p=>[p,`${p}`,RES_DESC[p]])];}
function resolutionSheet(){const opts=resOptions();if(!opts.some(o=>String(o[0])===String(state.resolution)))state.resolution='original';
return `<div class="res-head"><h3 class="res-section-label">Video quality</h3><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><div class="res-list" role="radiogroup" aria-label="Video quality">${opts.map(([v,label,desc])=>`<button class="res-row" role="radio" aria-checked="${String(v)===String(state.resolution)}" data-action="res-pick" data-value="${v}"><span class="res-radio" aria-hidden="true"></span><span class="res-text"><strong>${label}</strong><small>${desc}</small></span></button>`).join('')}</div><button class="primary res-apply" data-action="res-confirm" aria-label="Apply export settings">${icon('check')} Apply</button>`;}
function sheet(){let body='';if(state.sheet==='export-preview'){body=`<div class="sheet-header"><h2>Save preview</h2><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><p>This prototype exports the current preview as a PNG image.</p><button class="primary" data-action="download-preview">${icon('download')} Download PNG</button>`;}else if(state.sheet==='time'){const r=selected();body=`<div class="sheet-header"><h2>When should it apply?</h2><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><p>${r.kind==='box'?'Box':'Lasso'} ${r.id} · enter seconds or ${state.duration>=3600?'h:mm:ss.ss':'m:ss.ss'}</p><div class="input-row"><label>Start<input id="start-time" type="text" value="${timeText(r.start,true)}" inputmode="text"></label><label>End<input id="end-time" type="text" value="${timeText(r.end,true)}" inputmode="text"></label></div><div class="form-error" id="time-error" role="alert"></div><button class="primary" data-action="apply-time">Apply interval</button><button class="text-button" data-action="full-time" style="width:100%;margin-top:8px">Apply to entire video</button>`;}else if(state.sheet==='menu'){const themeLabel={system:'System',light:'Light',dark:'Dark'}[state.themeMode]||'System';body=`<nav class="menu-list" aria-label="App menu">${[['share-app','share','Share App',''],['menu-demo','ads','Remove Ads','Remove Ads opens the paywall. It is not part of this prototype.'],['menu-demo','star','Rate App','Rate App opens the Google Play rating dialog. Demo only.'],['menu-demo','privacy','Privacy Policy','Privacy Policy opens as a web page. Demo only.'],['menu-demo','terms','Terms And Conditions','Terms And Conditions open as a web page. Demo only.'],['menu-demo','support','Customer Support','Customer Support opens the support form. Demo only.']].map(([a,g,label,note])=>`<button class="menu-row" data-action="${a}" data-note="${note}">${icon(g)}<span>${label}</span></button>`).join('')}<button class="menu-row" data-action="open-theme">${icon('theme')}<span>Theme</span><small class="menu-value">${themeLabel}</small>${icon('chevron')}</button></nav>`;}else if(state.sheet==='theme'){body=`<div class="sheet-header"><h2>Theme</h2><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><div class="theme-grid" role="radiogroup" aria-label="Theme">${[['system','phone','System'],['light','sun','Light'],['dark','moon','Dark']].map(([v,g,label])=>`<button class="theme-card" role="radio" aria-checked="${state.themeMode===v}" data-action="theme-pick" data-value="${v}">${icon(g)}<strong>${label}</strong></button>`).join('')}</div>`;}else if(state.sheet==='resolution'){body=resolutionSheet();}else if(state.sheet==='share-app'){body=shareAppSheet();}else if(state.sheet==='system-share'){body=systemShareSheet();}else if(state.sheet==='share'){body=`<div class="sheet-header"><h2>Share your result</h2><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><p>Sharing to social apps is a demo. You can download the preview as an image.</p><button class="primary" data-action="download-preview">${icon('download')} Download preview</button>`;}const drawer=state.sheet==='menu';return `<div class="sheet-backdrop${drawer?' drawer-backdrop':''}"><section class="sheet${state.sheet==='share-app'?' share-app-sheet':state.sheet==='system-share'?' share-app-sheet sys-share-sheet':drawer?' menu-drawer':''}" role="dialog" aria-modal="true" tabindex="-1">${drawer?'':'<div class="sheet-handle"></div>'}${body}</section></div>`;}
const HERO_INTRO_MS=3000,HERO_INTRO_KF=[{offset:0,'--split':'50%'},{offset:.1,'--split':'50%',easing:'ease-in-out'},{offset:.33333,'--split':'22.22%',easing:'ease-in-out'},{offset:.76667,'--split':'91.67%',easing:'ease-out'},{offset:.96667,'--split':'50%'},{offset:1,'--split':'50%'}];
let heroIntroStart=null,heroIntroAnim=null;
function playHeroIntro(){const hero=$('.hero');if(!hero||heroIntroStart===null)return;const t=performance.now()-heroIntroStart;if(t>=HERO_INTRO_MS||!hero.animate||matchMedia('(prefers-reduced-motion: reduce)').matches){heroIntroStart=null;return;}heroIntroAnim=hero.animate(HERO_INTRO_KF,{duration:HERO_INTRO_MS,easing:'linear'});heroIntroAnim.currentTime=t;heroIntroAnim.onfinish=()=>{heroIntroStart=null;};}
function stopHeroIntro(){heroIntroAnim?.cancel();heroIntroAnim=null;heroIntroStart=null;}
function render(){const previousFocus=document.activeElement?.dataset?.action;renderNav();renderGuide();const content=({home,edit:editor,result,viewer,gallery:galleryScreen,processing,intro})[state.screen]();$('#app').innerHTML=(state.screen==='home'||state.screen==='viewer'?'':statusBar())+content+(state.sheet?sheet():'');for(const child of $('#app').children)child.inert=!!state.sheet&&!child.classList.contains('sheet-backdrop');if(state.screen==='home')playHeroIntro();try{history.replaceState(null,'','#'+(state.screen==='edit'?'editor':state.screen));}catch{}if(state.screen==='edit'&&state.tool!=='crop')persistDraft();requestAnimationFrame(()=>{fitPlane();const track=$('.track.active'),tracks=$('.tracks');if(track&&tracks){const row=track.parentElement;if(row.offsetTop+row.offsetHeight+8>tracks.scrollTop+tracks.clientHeight)tracks.scrollTop=row.offsetTop+row.offsetHeight+8-tracks.clientHeight;else if(row.offsetTop-8<tracks.scrollTop)tracks.scrollTop=Math.max(0,row.offsetTop-8);updateTrackEdges();}if(state.sheet){const dialog=$('.sheet');dialog?.setAttribute('aria-label',dialog.querySelector('h2')?.textContent||'Options');const target=state.sheet==='time'?$('#start-time'):state.sheet==='resolution'?dialog?.querySelector('.res-row[aria-checked="true"]'):dialog?.querySelector('button');target?.focus({preventScroll:true});}else if(previousFocus){$(`[data-action="${previousFocus}"]`)?.focus({preventScroll:true});}});}
function fitDevice(){const mobile=innerWidth<=720,baseW=mobile?360:372,baseH=mobile?800:812,scale=Math.min(1,(mobile?innerWidth:372)/baseW,Math.max(320,innerHeight-(mobile?0:128))/baseH),shell=$('.device-viewport'),device=$('.device'),area=$('.device-area');if(shell&&device){shell.style.width=baseW*scale+'px';shell.style.height=baseH*scale+'px';device.style.transform='scale('+scale+')';area.style.width=baseW*scale+'px';} }
function updateTrackEdges(){const tracks=$('.tracks');if(!tracks)return;const shell=tracks.parentElement;shell.classList.toggle('can-scroll-up',tracks.scrollTop>2);shell.classList.toggle('can-scroll-down',tracks.scrollTop+tracks.clientHeight<tracks.scrollHeight-2);}
function fitSceneOverlays(){for(const [imageSelector,overlaySelector,area] of [['.intro-photo','.intro-mark',{x:.57,y:.65,w:.19,h:.13}]]){const img=$(imageSelector),overlay=$(overlaySelector);if(!img||!overlay)continue;const sourceW=img.naturalWidth||1264,sourceH=img.naturalHeight||848,w=img.clientWidth,h=img.clientHeight,scale=Math.max(w/sourceW,h/sourceH),left=(w-sourceW*scale)*.55,top=(h-sourceH*scale)/2;Object.assign(overlay.style,{left:(left+area.x*sourceW*scale)+'px',top:(top+area.y*sourceH*scale)+'px',width:(area.w*sourceW*scale)+'px',height:(area.h*sourceH*scale)+'px'});}}
function fitPlane(){fitDevice();fitSceneOverlays();updateTrackEdges();const p=$('.media-plane'),container=p?.parentElement;if(!p||!container)return;const maxH=container.clientHeight,maxW=container.clientWidth;const w=Math.min(maxW,maxH*state.aspect);p.style.width=w+'px';p.style.height=w/state.aspect+'px';const svg=p.querySelector('.selection-svg');if(svg){svg.style.setProperty('--sx',w/100);svg.style.setProperty('--sy',w/state.aspect/100);}}
function addRegion(){if(state.tool==='lasso'){toast('Trace around an object to add a Lasso area');return;}remember();const offset=(state.regions.length%3)*7;const r={id:state.nextId++,kind:'box',x:57-offset,y:65-offset,w:19,h:13,start:0,end:state.duration};state.regions.push(r);state.selected=r.id;render();}
function removeRegion(){if(!selected())return;remember();state.regions=state.regions.filter(r=>r.id!==state.selected);state.selected=state.regions.at(-1)?.id??null;render();}

async function mediaEffectImage(src,regions){const img=await loadImage(src),canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);for(const r of regions){ctx.save();ctx.beginPath();if(r.points){r.points.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](p.x/100*canvas.width,p.y/100*canvas.height));ctx.closePath();}else ctx.rect(r.x/100*canvas.width,r.y/100*canvas.height,r.w/100*canvas.width,r.h/100*canvas.height);ctx.clip();ctx.filter='blur(13px)';ctx.drawImage(img,0,0);ctx.restore();}return canvas.toDataURL('image/jpeg',.92);}
async function resultThumbnail(){const img=await loadImage(state.src),c=document.createElement('canvas');c.width=320;c.height=Math.round(320/state.aspect);const x=c.getContext('2d');x.drawImage(img,0,0,c.width,c.height);for(const r of state.regions.filter(r=>state.type!=='video'||(state.regions[0].start+.01>=r.start&&state.regions[0].start+.01<=r.end))){x.save();x.beginPath();if(r.points){r.points.forEach((p,i)=>x[i?'lineTo':'moveTo'](p.x/100*c.width,p.y/100*c.height));x.closePath();}else x.rect(r.x/100*c.width,r.y/100*c.height,r.w/100*c.width,r.h/100*c.height);x.clip();x.filter='blur(5px)';x.drawImage(img,0,0,c.width,c.height);x.restore();}return c.toDataURL('image/jpeg',.82);}

function startProcessing(){if(!state.regions.length)return;stopPlayback();state.screen='processing';state.progress=0;state.sheet=null;render();processTimer=setInterval(async()=>{state.progress=Math.min(100,state.progress+Math.max(1,Math.round((5+Math.round(Math.random()*7))*(state.type==='video'?speedInfo()[4]:1))));const fill=$('.progress-fill'),txt=$('.processing-percent');if(fill)fill.style.width=state.progress+'%';$('.progress-shell')?.setAttribute('aria-valuenow',state.progress);if(txt)txt.textContent=state.progress+'%';if(state.progress===100){clearInterval(processTimer);processTimer=null;const item={id:Date.now(),src:state.src,aspect:state.aspect,type:state.type,duration:state.duration,resolution:state.type==='video'?resLabel():null,speed:state.type==='video'?speedInfo()[1]:null,regions:JSON.parse(JSON.stringify(state.regions))};try{item.preview=await resultThumbnail();state.effectSrc=await mediaEffectImage(state.src,state.regions);item.effectSrc=state.effectSrc;}catch{}if(state.screen!=='processing')return;gallery.unshift(item);state.savedId=item.id;state.savedSignature=mediaSignature();state.resultFrom='home';persistDraft();saveGallery();state.time=Math.min(state.duration,state.regions[0].start+.01);state.zoom=1;state.pan={x:0,y:0};go('result');}},170);}
function togglePlay(){if(state.playing){stopPlayback();render();return;}if(state.time>=state.duration)state.time=0;state.playing=true;state.controlsHidden=false;render();scheduleHideControls();let last=performance.now();playTimer=setInterval(()=>{const now=performance.now();state.time=Math.min(state.duration,state.time+(now-last)/1000);last=now;updateTimeUI();if(state.time>=state.duration){stopPlayback();render();}},60);}
