function finishDrag(cancelled=false){if(!drag)return;const d=drag;drag=null;if(cancelled&&['move','resize'].includes(d.mode)){Object.assign(state.regions.find(r=>r.id===d.id),d.original);if(d.historySaved)state.history.pop();}if(cancelled&&d.mode==='time'){Object.assign(state.regions.find(r=>r.id===d.id),d.original);state.time=d.previousTime;state.history.pop();}if(d.mode==='draw'){const r=state.regions.find(r=>r.id===d.id);if(cancelled||!r||r.w<2||r.h<2||(r.kind==='lasso'&&r.points.length<4)){state.regions=state.regions.filter(r=>r.id!==d.id);state.selected=state.regions.at(-1)?.id??null;state.history.pop();}}render();}
document.addEventListener('scroll',e=>{if(e.target.classList?.contains('tracks'))updateTrackEdges();},true);
document.addEventListener('pointerup',()=>finishDrag());document.addEventListener('pointercancel',()=>finishDrag(true));window.addEventListener('resize',fitPlane);document.addEventListener('load',e=>{if(e.target.tagName==='IMG')fitPlane();},true);
let touchPan=null;document.addEventListener('touchstart',e=>{if(state.screen==='edit'&&e.touches.length===2&&e.target.closest('.stage')){if(drag?.mode==='draw')finishDrag(true);const [a,b]=e.touches;touchPan={distance:Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY),zoom:state.zoom,x:(a.clientX+b.clientX)/2,y:(a.clientY+b.clientY)/2,pan:{...state.pan}};e.preventDefault();}},{passive:false});document.addEventListener('touchmove',e=>{if(!touchPan||e.touches.length!==2)return;e.preventDefault();const [a,b]=e.touches;state.zoom=clamp(touchPan.zoom*Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY)/touchPan.distance,1,3);state.pan={x:clamp(touchPan.pan.x+(a.clientX+b.clientX)/2-touchPan.x,-160,160),y:clamp(touchPan.pan.y+(a.clientY+b.clientY)/2-touchPan.y,-160,160)};const p=$('.media-plane');if(p)p.style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom})`;},{passive:false});document.addEventListener('touchend',()=>{if(touchPan){touchPan=null;render();}});
